IoT
| extend parsed = todynamic(rawdata)
| mv-expand sensor = parsed.data
| extend 
    machineId = tostring(parsed.machineId),
    workOrderId = tostring(parsed.workOrderId),
    sensorName = tostring(sensor.name),
    // Convertimos el timestamp de microsegundos del JSON a un tipo Datetime real de KQL
    EventTime = unixtime_microseconds_todatetime(tolong(sensor.timestamp)),
    // Extraemos el primer valor numérico del array de 'values'
    SensorValue = todouble(sensor.values[0])
// 5. FILTRADO CRÍTICO (Nota: Tu data de ejemplo es del 13 de abril de 2022, 
// por lo que 'ago(3d)' te devolvería vacío. Filtramos por ese rango de fechas real)
| where EventTime >= datetime(2022-04-10) and EventTime <= datetime(2022-04-15)
// 6. PROYECCIÓN: Conservamos solo las columnas limpias y tipadas
| project EventTime, machineId, sensorName, SensorValue
// 7. AGRUPACIÓN: Promedio de lectura del sensor en cajones de 1 hora
| summarize AvgValue = avg(SensorValue) by bin(EventTime, 1h), machineId, sensorName
// 8. ORDENAMIENTO
| sort by EventTime asc
// 9. VISUALIZACIÓN
| render timechart
